export const CREDIT_TEXT = '模板相应的主题直达：欢迎留言~任何建议反馈都是我更新的动力';

/** 存"已经装过哪些"的设置键（值是 id 数组）。 */
export const SEEDED_KEY = 'stcr:ui:card:bundled:v1';

/**
 * 把还没装过的附带模板加进用户的自制模板。
 * - 装过的（在 seeded 里）不再装：用户删掉就是删掉了。
 * - 用户已经有同名模板（比如自己导入过）：不重复加，算装过。
 * - 自制模板满了：这次跳过，不记为装过，以后有空位再装。
 * @param {object[]} list 规范化后的自制模板
 * @param {unknown} seeded 存储里读出的 id 数组
 * @param {(list:object[], template:object, opts:object) => {ok:boolean, list?:object[]}} add cardTemplates.addTemplate
 * @returns {{ list: object[], seeded: string[], changed: boolean }}
 */
export function seedBundled(list, seeded, add) {
    const done = new Set(Array.isArray(seeded) ? seeded.filter(id => typeof id === 'string') : []);
    let out = list, changed = false;
    for (const item of BUNDLED_TEMPLATES) {
        if (done.has(item.id)) continue;
        if (out.some(t => t.id === item.id || t.name === item.name)) { done.add(item.id); changed = true; continue; }
        const result = add(out, { name: item.name, base: item.base, options: item.options, css: item.css }, { rename: false, id: item.id });
        if (!result.ok) continue;
        out = result.list;
        done.add(item.id);
        changed = true;
    }
    return { list: out, seeded: [...done], changed };
}

/** 当前用的自制模板是哪套附带主题（按 id，改过名的也算；没有 id 对上再按原名）→ 链接，或 null。 */
export function bundledLinks(template) {
    if (!template) return null;
    const item = BUNDLED_TEMPLATES.find(t => t.id === template.id) ?? BUNDLED_TEMPLATES.find(t => t.name === template.name);
    return item ? BUNDLED_LINKS[item.theme] ?? null : null;
}
